"""Build a portable offline research report from computed outputs (no backend)."""
import base64
import html
import json
from pathlib import Path
import numpy as np
root=Path(__file__).resolve().parents[1]
def pic(p): return 'data:image/png;base64,'+base64.b64encode((root/p).read_bytes()).decode()
r=json.loads((root/'reports/experiment/results.json').read_text())
s=json.loads((root/'reports/sentinel_summary.json').read_text())
manifest=json.loads((root/'data/metadata/sentinel_manifest.json').read_text())
g=json.loads((root/'reports/gfd_audit.json').read_text())
idx=np.load(root/'data/processed/sentinel_indices.npz')['dnbr']
data={'width':idx.shape[1],'height':idx.shape[0],'values':[float(v) if np.isfinite(v) else None for v in idx.flat]}
table=''
for f in [.05,.1,.2,1.]:
    row=[x for x in r['summary'] if x['label_fraction']==f]
    table+='<tr><th>%'+str(int(f*100))+'</th>'+''.join(f'<td>{x["macro_f1_mean"]:.3f} <small>± {x["macro_f1_std"]:.3f}</small></td>' for x in row)+'</tr>'
dates=' → '.join(x['datetime'][:10] for x in manifest['scenes'])
gfd=''.join(f'<tr><td>{x["file"]}</td><td>{x["shape"][0]:,} × {x["shape"][1]:,}</td><td>{len(x["counts"])}</td><td>Yok</td></tr>' for x in g)
